// Monta o snapshot v2 a partir da "Controle Financeiro Simples".
//
// A entrada e a resposta de um values:batchGet que pediu TODAS as abas da
// planilha, pelo nome descoberto no no anterior. Nada aqui depende da ordem das
// abas nem do nome delas: cada aba e reconhecida pela linha de cabecalho, e
// cada coluna e lida pelo rotulo, nao pelo indice. Foi uma versao que dependia
// de indice fixo (vr[0], vr[1], ...) que publicou um snapshot vazio por cima de
// um bom, sem erro nenhum.

function parseBRL(v) {
  if (v === null || v === undefined) return null;
  let s = String(v).trim();
  if (s === '' || s === '-' || s === '—') return null;
  let neg = false;
  if (s.startsWith('(') && s.endsWith(')')) { neg = true; s = s.slice(1, -1); }
  if (s.startsWith('-R$') || s.startsWith('- R$')) { neg = true; s = s.replace('-', ''); }
  const n = parseFloat(s.replace(/[^\d,.\-]/g, '').replace(/\./g, '').replace(',', '.'));
  if (isNaN(n)) return null;
  return neg ? -Math.abs(n) : n;
}
function parsePct(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function parseInt_(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseInt(String(v).replace(/[^\d\-]/g, ''), 10);
  return isNaN(n) ? null : n;
}
function clean(v) { return (v ?? '').toString().trim(); }
// Chave de comparacao: sem acento, caixa alta, espacos colapsados. O Sheets
// pode devolver acento decomposto ou espaco nao-quebravel, e comparar texto
// acentuado na unha faz o rotulo "sumir" sem erro.
function norm(s) {
  return clean(s).normalize('NFD').split('').filter(function (c) {
    const x = c.charCodeAt(0);
    return x < 0x300 || x > 0x36f;
  }).join('').toUpperCase().replace(/\s+/g, ' ').trim();
}

const resp = $input.first().json;
const vr = resp.valueRanges;
if (!Array.isArray(vr) || vr.length === 0) {
  throw new Error('O batchGet nao devolveu nenhum range. Resposta: ' +
    JSON.stringify(resp).slice(0, 400));
}

// Cada aba vira { linhas, cabecalho, col } assim que casar com uma assinatura.
const abas = vr.map(function (r) { return (r && r.values) || []; });

// Procura, dentro de uma aba, a linha cujo conteudo contem todos os rotulos
// pedidos. Devolve o indice da linha e o mapa rotulo -> coluna.
function casaCabecalho(linhas, obrigatorios) {
  for (let i = 0; i < linhas.length; i++) {
    const cels = (linhas[i] || []).map(norm);
    if (obrigatorios.every(function (o) { return cels.indexOf(norm(o)) !== -1; })) {
      const col = {};
      cels.forEach(function (c, j) { if (c && !(c in col)) col[c] = j; });
      return { inicio: i + 1, col: col };
    }
  }
  return null;
}

// Acha a aba que satisfaz a assinatura, varrendo todas as abas recebidas.
function acharAba(obrigatorios, apelido) {
  for (const linhas of abas) {
    const m = casaCabecalho(linhas, obrigatorios);
    if (m) return { linhas: linhas, inicio: m.inicio, col: m.col };
  }
  throw new Error('Nao encontrei a aba de ' + apelido + ': nenhuma das ' +
    abas.length + ' abas tem uma linha de cabecalho com ' +
    obrigatorios.join(' + ') + '.');
}

// Leitor de celula por rotulo de coluna.
function leitor(aba) {
  return function (linha, rotulo) {
    const j = aba.col[norm(rotulo)];
    return j === undefined ? '' : clean(linha[j]);
  };
}
function linhasDe(aba) { return aba.linhas.slice(aba.inicio); }

// ---- Dashboard: pares rotulo/valor em duas colunas ----
// Nao tem cabecalho tabular; e reconhecida por conter "Posicao financeira".
let dashRows = null;
for (const linhas of abas) {
  if (linhas.some(function (r) { return norm((r || [])[0]) === 'POSICAO FINANCEIRA'; })) {
    dashRows = linhas;
    break;
  }
}
if (!dashRows) {
  throw new Error('Nao encontrei a aba Dashboard: nenhuma aba tem a linha ' +
    '"Posicao financeira" na primeira coluna.');
}
const dashMap = {};
for (const row of dashRows) {
  if (!row || row.length < 2) continue;
  const label = norm(row[0]);
  if (label && !(label in dashMap)) dashMap[label] = clean(row[1]);
}
const get = function (label) { return dashMap[norm(label)]; };

const posicaoFinanceira = {
  caixaDisponivel: parseBRL(get('Caixa disponível')) ?? 0,
  contasReceber: parseBRL(get('Contas a receber')) ?? 0,
  contasPagar: parseBRL(get('Contas a pagar')) ?? 0,
  estoquePeloCusto: parseBRL(get('Estoque pelo custo')) ?? 0,
  valoresReceberSocio: parseBRL(get('Valores a receber do sócio (retiradas)')) ?? 0,
  ativosOperacionais: parseBRL(get('Ativos operacionais')) ?? 0,
  emprestimosRecebidos: parseBRL(get('Empréstimos recebidos')) ?? 0,
  emprestimosPagos: parseBRL(get('Empréstimos pagos')) ?? 0,
  saldoEmprestimosPagar: parseBRL(get('Saldo de empréstimos a pagar')) ?? 0,
  patrimonioLiquido: parseBRL(get('Patrimônio líquido')) ?? 0,
};
const dreAcumulada = {
  vendasBrutas: parseBRL(get('Vendas brutas')) ?? 0,
  taxasVendas: parseBRL(get('Taxas das vendas')) ?? 0,
  vendasLiquidas: parseBRL(get('Vendas líquidas')) ?? 0,
  custoItensVendidos: parseBRL(get('Custo dos itens vendidos')) ?? 0,
  despesasOperacionais: parseBRL(get('Despesas operacionais')) ?? 0,
  receitaVendasTerceiros: parseBRL(get('Receita com vendas de terceiros')) ?? 0,
  resultadoLiquido: parseBRL(get('Resultado líquido')) ?? 0,
};
const indicadores = {
  itensEstoque: parseInt_(get('Itens atuais no estoque')) ?? 0,
  itensVendidos: parseInt_(get('Itens vendidos')) ?? 0,
  margemLiquidaAcumulada: parsePct(get('Margem líquida acumulada')) ?? 0,
};

// ---- Estoque e vendas ----
const abaEstoque = acharAba(['Data da compra', 'Item', 'Custo final'], 'Estoque');
const cEst = leitor(abaEstoque);
const estoque = linhasDe(abaEstoque)
  .filter(function (r) { return r && cEst(r, 'Item'); })
  .map(function (r) {
    return {
      dataCompra: cEst(r, 'Data da compra') || null,
      item: cEst(r, 'Item'),
      origem: cEst(r, 'Origem') || null,
      valorBase: parseBRL(cEst(r, 'Valor base')),
      comissao: parseBRL(cEst(r, 'Comissão')),
      iof: parseBRL(cEst(r, 'IOF')),
      frete: parseBRL(cEst(r, 'Frete')),
      imposto: parseBRL(cEst(r, 'Imposto')),
      outrosCustos: parseBRL(cEst(r, 'Outros custos')),
      custoFinal: parseBRL(cEst(r, 'Custo final')),
      dataVenda: cEst(r, 'Data da venda') || null,
      canalVenda: cEst(r, 'Canal da venda') || null,
      valorVenda: parseBRL(cEst(r, 'Valor da venda')),
      taxasVenda: parseBRL(cEst(r, 'Taxas da venda')),
      valorLiquido: parseBRL(cEst(r, 'Valor líquido')),
      lucro: parseBRL(cEst(r, 'Lucro')),
      margem: parsePct(cEst(r, 'Margem')),
    };
  });

// ---- Vendas de terceiros (consignacao) ----
const abaTerceiros = acharAba(['Data da venda', 'Relógio', 'Proprietário'], 'Vendas de Terceiros');
const cTer = leitor(abaTerceiros);
const vendasTerceiros = linhasDe(abaTerceiros)
  .filter(function (r) { return r && cTer(r, 'Relógio'); })
  .map(function (r) {
    return {
      dataVenda: cTer(r, 'Data da venda') || null,
      relogio: cTer(r, 'Relógio'),
      proprietario: cTer(r, 'Proprietário') || null,
      valorTotalVendido: parseBRL(cTer(r, 'Valor total vendido')),
      valorRepassar: parseBRL(cTer(r, 'Valor a repassar')),
      comissaoLoja: parseBRL(cTer(r, 'Comissão da loja')),
      taxasDespesas: parseBRL(cTer(r, 'Taxas/despesas')),
      receitaLiquida: parseBRL(cTer(r, 'Receita líquida')),
      recebido: cTer(r, 'Recebido?') || null,
      dataRecebimento: cTer(r, 'Data do recebimento') || null,
      formaPagamento: cTer(r, 'Forma de pagamento') || null,
      observacoes: cTer(r, 'Observações') || null,
    };
  });

// ---- Caixa ----
const abaCaixa = acharAba(['Data', 'Descrição', 'Realizado?', 'Saldo'], 'Caixa');
const cCx = leitor(abaCaixa);
const caixa = linhasDe(abaCaixa)
  .filter(function (r) { return r && cCx(r, 'Descrição'); })
  .map(function (r) {
    return {
      data: cCx(r, 'Data') || null,
      descricao: cCx(r, 'Descrição'),
      categoria: cCx(r, 'Categoria') || null,
      itemRelacionado: cCx(r, 'Item relacionado') || null,
      vencimento: cCx(r, 'Vencimento') || null,
      realizado: cCx(r, 'Realizado?') || null,
      entrada: parseBRL(cCx(r, 'Entrada')),
      saida: parseBRL(cCx(r, 'Saída')),
      formaPagamento: cCx(r, 'Forma de pagamento') || null,
      saldo: parseBRL(cCx(r, 'Saldo')),
    };
  });

// ---- Gerenciador de anuncios ----
const abaAnuncios = acharAba(['Data', 'Campanha', 'CTR'], 'Gerenciador de Anúncios');
const cAn = leitor(abaAnuncios);
const anuncios = linhasDe(abaAnuncios)
  .filter(function (r) { return r && cAn(r, 'Data'); })
  .map(function (r) {
    return {
      data: cAn(r, 'Data') || null,
      campanha: cAn(r, 'Campanha') || null,
      alcance: parseInt_(cAn(r, 'Alcance')),
      impressoes: parseInt_(cAn(r, 'Impressões')),
      cliques: parseInt_(cAn(r, 'Cliques no link')),
      cpc: parseBRL(cAn(r, 'CPC')),
      ctr: parsePct(cAn(r, 'CTR')),
      valorGasto: parseBRL(cAn(r, 'Valor gasto')),
      resultados: parseInt_(cAn(r, 'Resultados')),
      custoPorResultado: parseBRL(cAn(r, 'Custo por resultado')),
    };
  });

// ---- Travas ----
// Publicar um snapshot vazio por cima de um bom deixa o painel em branco sem
// nenhum sinal de erro. E exatamente o que aconteceu em 14/09/2026. Melhor a
// execucao falhar, visivel no n8n, do que o painel apagar em silencio.
if (caixa.length === 0) {
  throw new Error('A aba Caixa veio sem nenhum lancamento. Abortado para nao ' +
    'publicar um snapshot vazio por cima do atual.');
}
if (estoque.length === 0) {
  throw new Error('A aba Estoque veio sem nenhum item. Abortado para nao ' +
    'publicar um snapshot vazio por cima do atual.');
}
if (posicaoFinanceira.caixaDisponivel === 0 && dreAcumulada.vendasBrutas === 0) {
  throw new Error('O Dashboard veio todo zerado (caixa e vendas em 0). Rotulos ' +
    'lidos: ' + Object.keys(dashMap).slice(0, 20).join(' | '));
}

// Conferencia, nao trava: o saldo da ultima linha do Caixa deve bater com o
// "Caixa disponivel" do Dashboard. Divergir nao impede publicar -- pode ser
// ordenacao ou linha pendente -- mas fica registrado pra diagnostico.
const ultimoSaldo = caixa.length ? caixa[caixa.length - 1].saldo : null;
const bateSaldo = ultimoSaldo !== null &&
  Math.abs(ultimoSaldo - posicaoFinanceira.caixaDisponivel) < 0.01;

const snapshot = {
  updatedAt: new Date().toISOString(),
  posicaoFinanceira,
  dreAcumulada,
  indicadores,
  estoque,
  vendasTerceiros,
  caixa,
  anuncios,
};

const texto = JSON.stringify(snapshot, null, 2);

return [{
  json: {
    contentB64: Buffer.from(texto, 'utf-8').toString('base64'),
    resumo: {
      abasRecebidas: abas.length,
      itensEstoque: estoque.length,
      vendasTerceiros: vendasTerceiros.length,
      lancamentosCaixa: caixa.length,
      diasDeAnuncio: anuncios.length,
      bytes: Buffer.byteLength(texto, 'utf-8'),
      caixaDisponivel: posicaoFinanceira.caixaDisponivel,
      ultimoSaldoDoCaixa: ultimoSaldo,
      saldoConfere: bateSaldo,
    },
  },
}];
